#ifdef NDEBUG
#error "Assertions must remain enabled."
#endif
#include <cassert>
#include <iostream>
enum class Phase{Playing,Failed};
class Run{
    Phase phase_=Phase::Playing;
    int hp_=3, enemies_=2, attempt_=1, best_=0;
public:
    bool fail(int score){
        if(phase_!=Phase::Playing || score<0)return false;
        if(score>best_)best_=score;
        hp_=0;phase_=Phase::Failed;return true;
    }
    bool retry(){
        if(phase_!=Phase::Failed)return false;
        hp_=3;enemies_=2;++attempt_;phase_=Phase::Playing;return true;
    }
    int hp()const{return hp_;}int enemies()const{return enemies_;}
    int attempt()const{return attempt_;}int best()const{return best_;}
};
int main(){
    Run r;assert(!r.retry());assert(!r.fail(-1));
    assert(r.fail(20));assert(!r.fail(99));
    assert(r.retry());assert(!r.retry());
    assert(r.hp()==3 && r.enemies()==2 && r.attempt()==2 && r.best()==20);
    assert(r.fail(5));assert(r.retry());assert(r.best()==20);
    std::cout<<"retry reset tests passed\n";
}
